decode_msg_room(Bin, TrUserData) ->
    dfp_read_field_def_room(Bin, 0, 0, 0, id(<<>>, TrUserData), id('ROOM_KIND_UNSPECIFIED', TrUserData), id(<<>>, TrUserData), id(<<>>, TrUserData), id(false, TrUserData), id('$undef', TrUserData), id([], TrUserData), TrUserData).

