d_field_room_created_at(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData) when N < 57 -> d_field_room_created_at(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData);
d_field_room_created_at(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, F@_3, F@_4, F@_5, Prev, F@_7, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_timestamp(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_room(RestF,
                            0,
                            0,
                            F,
                            F@_1,
                            F@_2,
                            F@_3,
                            F@_4,
                            F@_5,
                            if Prev == '$undef' -> NewFValue;
                               true -> merge_msg_timestamp(Prev, NewFValue, TrUserData)
                            end,
                            F@_7,
                            TrUserData).

