skip_varint_list_messages_request(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, F@_3, F@_4, TrUserData) -> dfp_read_field_def_list_messages_request(Rest, Z1, Z2, F, F@_1, F@_2, F@_3, F@_4, TrUserData).

skip_length_delimited_list_messages_request(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, F@_3, F@_4, TrUserData) when N < 57 -> skip_length_delimited_list_messages_request(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, F@_3, F@_4, TrUserData);
skip_length_delimited_list_messages_request(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, F@_3, F@_4, TrUserData) ->
    Length = X bsl N + Acc,
    <<_:Length/binary, Rest2/binary>> = Rest,
    dfp_read_field_def_list_messages_request(Rest2, 0, 0, F, F@_1, F@_2, F@_3, F@_4, TrUserData).

skip_group_list_messages_request(Bin, _, Z2, FNum, F@_1, F@_2, F@_3, F@_4, TrUserData) ->
    {_, Rest} = read_group(Bin, FNum),
    dfp_read_field_def_list_messages_request(Rest, 0, Z2, FNum, F@_1, F@_2, F@_3, F@_4, TrUserData).

skip_32_list_messages_request(<<_:32, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, F@_3, F@_4, TrUserData) -> dfp_read_field_def_list_messages_request(Rest, Z1, Z2, F, F@_1, F@_2, F@_3, F@_4, TrUserData).

skip_64_list_messages_request(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, F@_3, F@_4, TrUserData) -> dfp_read_field_def_list_messages_request(Rest, Z1, Z2, F, F@_1, F@_2, F@_3, F@_4, TrUserData).

decode_msg_list_messages_response(Bin, TrUserData) -> dfp_read_field_def_list_messages_response(Bin, 0, 0, 0, id([], TrUserData), id(<<>>, TrUserData), TrUserData).

dfp_read_field_def_list_messages_response(<<10, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> d_field_list_messages_response_messages(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
dfp_read_field_def_list_messages_response(<<18, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> d_field_list_messages_response_next_cursor(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
dfp_read_field_def_list_messages_response(<<>>, 0, 0, _, R1, F@_2, TrUserData) ->
    S1 = #{next_cursor => F@_2},
    if R1 == '$undef' -> S1;
       true -> S1#{messages => lists_reverse(R1, TrUserData)}
    end;
dfp_read_field_def_list_messages_response(Other, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dg_read_field_def_list_messages_response(Other, Z1, Z2, F, F@_1, F@_2, TrUserData).

dg_read_field_def_list_messages_response(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 32 - 7 -> dg_read_field_def_list_messages_response(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
dg_read_field_def_list_messages_response(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, F@_2, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_list_messages_response_messages(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        18 -> d_field_list_messages_response_next_cursor(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_list_messages_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                1 -> skip_64_list_messages_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                2 -> skip_length_delimited_list_messages_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                3 -> skip_group_list_messages_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                5 -> skip_32_list_messages_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData)
            end
    end;
dg_read_field_def_list_messages_response(<<>>, 0, 0, _, R1, F@_2, TrUserData) ->
    S1 = #{next_cursor => F@_2},
    if R1 == '$undef' -> S1;
       true -> S1#{messages => lists_reverse(R1, TrUserData)}
    end.

d_field_list_messages_response_messages(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> d_field_list_messages_response_messages(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
d_field_list_messages_response_messages(<<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, F@_2, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_message(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_list_messages_response(RestF, 0, 0, F, cons(NewFValue, Prev, TrUserData), F@_2, TrUserData).

d_field_list_messages_response_next_cursor(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> d_field_list_messages_response_next_cursor(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
d_field_list_messages_response_next_cursor(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, _, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bytes:Len/binary, Rest2/binary>> = Rest, Bytes2 = binary:copy(Bytes), {id(Bytes2, TrUserData), Rest2} end,
    dfp_read_field_def_list_messages_response(RestF, 0, 0, F, F@_1, NewFValue, TrUserData).

skip_varint_list_messages_response(<<1:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> skip_varint_list_messages_response(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
skip_varint_list_messages_response(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dfp_read_field_def_list_messages_response(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

skip_length_delimited_list_messages_response(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> skip_length_delimited_list_messages_response(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
skip_length_delimited_list_messages_response(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) ->
    Length = X bsl N + Acc,
    <<_:Length/binary, Rest2/binary>> = Rest,
    dfp_read_field_def_list_messages_response(Rest2, 0, 0, F, F@_1, F@_2, TrUserData).

skip_group_list_messages_response(Bin, _, Z2, FNum, F@_1, F@_2, TrUserData) ->
    {_, Rest} = read_group(Bin, FNum),
    dfp_read_field_def_list_messages_response(Rest, 0, Z2, FNum, F@_1, F@_2, TrUserData).

skip_32_list_messages_response(<<_:32, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dfp_read_field_def_list_messages_response(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

skip_64_list_messages_response(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dfp_read_field_def_list_messages_response(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

decode_msg_timestamp(Bin, TrUserData) -> dfp_read_field_def_timestamp(Bin, 0, 0, 0, id(0, TrUserData), id(0, TrUserData), TrUserData).

dfp_read_field_def_timestamp(<<8, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> d_field_timestamp_seconds(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
dfp_read_field_def_timestamp(<<16, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> d_field_timestamp_nanos(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
dfp_read_field_def_timestamp(<<>>, 0, 0, _, F@_1, F@_2, _) -> #{seconds => F@_1, nanos => F@_2};
dfp_read_field_def_timestamp(Other, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dg_read_field_def_timestamp(Other, Z1, Z2, F, F@_1, F@_2, TrUserData).

dg_read_field_def_timestamp(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 32 - 7 -> dg_read_field_def_timestamp(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
dg_read_field_def_timestamp(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, F@_2, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        8 -> d_field_timestamp_seconds(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        16 -> d_field_timestamp_nanos(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_timestamp(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                1 -> skip_64_timestamp(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                2 -> skip_length_delimited_timestamp(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                3 -> skip_group_timestamp(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                5 -> skip_32_timestamp(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData)
            end
    end;
dg_read_field_def_timestamp(<<>>, 0, 0, _, F@_1, F@_2, _) -> #{seconds => F@_1, nanos => F@_2}.

d_field_timestamp_seconds(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> d_field_timestamp_seconds(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
d_field_timestamp_seconds(<<0:1, X:7, Rest/binary>>, N, Acc, F, _, F@_2, TrUserData) ->
    {NewFValue, RestF} = {begin <<Res:64/signed-native>> = <<(X bsl N + Acc):64/unsigned-native>>, id(Res, TrUserData) end, Rest},
    dfp_read_field_def_timestamp(RestF, 0, 0, F, NewFValue, F@_2, TrUserData).

d_field_timestamp_nanos(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> d_field_timestamp_nanos(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
d_field_timestamp_nanos(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, _, TrUserData) ->
    {NewFValue, RestF} = {begin <<Res:32/signed-native>> = <<(X bsl N + Acc):32/unsigned-native>>, id(Res, TrUserData) end, Rest},
    dfp_read_field_def_timestamp(RestF, 0, 0, F, F@_1, NewFValue, TrUserData).

skip_varint_timestamp(<<1:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> skip_varint_timestamp(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
skip_varint_timestamp(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dfp_read_field_def_timestamp(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

skip_length_delimited_timestamp(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> skip_length_delimited_timestamp(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
skip_length_delimited_timestamp(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) ->
    Length = X bsl N + Acc,
    <<_:Length/binary, Rest2/binary>> = Rest,
    dfp_read_field_def_timestamp(Rest2, 0, 0, F, F@_1, F@_2, TrUserData).

skip_group_timestamp(Bin, _, Z2, FNum, F@_1, F@_2, TrUserData) ->
    {_, Rest} = read_group(Bin, FNum),
    dfp_read_field_def_timestamp(Rest, 0, Z2, FNum, F@_1, F@_2, TrUserData).

skip_32_timestamp(<<_:32, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dfp_read_field_def_timestamp(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

skip_64_timestamp(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dfp_read_field_def_timestamp(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

'd_enum_chat.v1.RoomKind'(0) -> 'ROOM_KIND_UNSPECIFIED';
'd_enum_chat.v1.RoomKind'(1) -> 'ROOM_KIND_DIRECT';
'd_enum_chat.v1.RoomKind'(2) -> 'ROOM_KIND_CHANNEL';
'd_enum_chat.v1.RoomKind'(V) -> V.

read_group(Bin, FieldNum) ->
    {NumBytes, EndTagLen} = read_gr_b(Bin, 0, 0, 0, 0, FieldNum),
    <<Group:NumBytes/binary, _:EndTagLen/binary, Rest/binary>> = Bin,
    {Group, Rest}.

%% Like skipping over fields, but record the total length,
%% Each field is <(FieldNum bsl 3) bor FieldType> ++ <FieldValue>
%% Record the length because varints may be non-optimally encoded.
%%
%% Groups can be nested, but assume the same FieldNum cannot be nested
%% because group field numbers are shared with the rest of the fields
%% numbers. Thus we can search just for an group-end with the same
%% field number.
%%
%% (The only time the same group field number could occur would
%% be in a nested sub message, but then it would be inside a
%% length-delimited entry, which we skip-read by length.)
read_gr_b(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen, FieldNum)
  when N < (32-7) ->
    read_gr_b(Tl, N+7, X bsl N + Acc, NumBytes, TagLen+1, FieldNum);
read_gr_b(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen,
          FieldNum) ->
    Key = X bsl N + Acc,
    TagLen1 = TagLen + 1,
    case {Key bsr 3, Key band 7} of
        {FieldNum, 4} -> % 4 = group_end
            {NumBytes, TagLen1};
        {_, 0} -> % 0 = varint
            read_gr_vi(Tl, 0, NumBytes + TagLen1, FieldNum);
        {_, 1} -> % 1 = bits64
            <<_:64, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 8, 0, FieldNum);
        {_, 2} -> % 2 = length_delimited
            read_gr_ld(Tl, 0, 0, NumBytes + TagLen1, FieldNum);
        {_, 3} -> % 3 = group_start
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 4} -> % 4 = group_end
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 5} -> % 5 = bits32
            <<_:32, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 4, 0, FieldNum)
    end.

read_gr_vi(<<1:1, _:7, Tl/binary>>, N, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_vi(Tl, N+7, NumBytes+1, FieldNum);
read_gr_vi(<<0:1, _:7, Tl/binary>>, _, NumBytes, FieldNum) ->
    read_gr_b(Tl, 0, 0, NumBytes+1, 0, FieldNum).

read_gr_ld(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_ld(Tl, N+7, X bsl N + Acc, NumBytes+1, FieldNum);
read_gr_ld(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum) ->
    Len = X bsl N + Acc,
    NumBytes1 = NumBytes + 1,
    <<_:Len/binary, Tl2/binary>> = Tl,
    read_gr_b(Tl2, 0, 0, NumBytes1 + Len, 0, FieldNum).

merge_msgs(Prev, New, MsgName) when is_atom(MsgName) -> merge_msgs(Prev, New, MsgName, []).

merge_msgs(Prev, New, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        room -> merge_msg_room(Prev, New, TrUserData);
        get_or_create_direct_request -> merge_msg_get_or_create_direct_request(Prev, New, TrUserData);
        get_or_create_direct_response -> merge_msg_get_or_create_direct_response(Prev, New, TrUserData);
        create_channel_request -> merge_msg_create_channel_request(Prev, New, TrUserData);
        create_channel_response -> merge_msg_create_channel_response(Prev, New, TrUserData);
        get_room_request -> merge_msg_get_room_request(Prev, New, TrUserData);
        get_room_response -> merge_msg_get_room_response(Prev, New, TrUserData);
        check_membership_request -> merge_msg_check_membership_request(Prev, New, TrUserData);
        check_membership_response -> merge_msg_check_membership_response(Prev, New, TrUserData);
        list_rooms_request -> merge_msg_list_rooms_request(Prev, New, TrUserData);
        room_summary -> merge_msg_room_summary(Prev, New, TrUserData);
        list_rooms_response -> merge_msg_list_rooms_response(Prev, New, TrUserData);
        add_member_request -> merge_msg_add_member_request(Prev, New, TrUserData);
        add_member_response -> merge_msg_add_member_response(Prev, New, TrUserData);
        member -> merge_msg_member(Prev, New, TrUserData);
        list_members_request -> merge_msg_list_members_request(Prev, New, TrUserData);
        list_members_response -> merge_msg_list_members_response(Prev, New, TrUserData);
        remove_member_request -> merge_msg_remove_member_request(Prev, New, TrUserData);
        remove_member_response -> merge_msg_remove_member_response(Prev, New, TrUserData);
        leave_room_request -> merge_msg_leave_room_request(Prev, New, TrUserData);
        leave_room_response -> merge_msg_leave_room_response(Prev, New, TrUserData);
        message -> merge_msg_message(Prev, New, TrUserData);
        send_message_request -> merge_msg_send_message_request(Prev, New, TrUserData);
        send_message_response -> merge_msg_send_message_response(Prev, New, TrUserData);
        list_messages_request -> merge_msg_list_messages_request(Prev, New, TrUserData);
        list_messages_response -> merge_msg_list_messages_response(Prev, New, TrUserData);
        timestamp -> merge_msg_timestamp(Prev, New, TrUserData)
    end.

-compile({nowarn_unused_function,merge_msg_room/3}).
merge_msg_room(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{kind := NFkind}} -> S2#{kind => NFkind};
             {#{kind := PFkind}, _} -> S2#{kind => PFkind};
             _ -> S2
         end,
    S4 = case {PMsg, NMsg} of
             {_, #{name := NFname}} -> S3#{name => NFname};
             {#{name := PFname}, _} -> S3#{name => PFname};
             _ -> S3
         end,
    S5 = case {PMsg, NMsg} of
             {_, #{owner_id := NFowner_id}} -> S4#{owner_id => NFowner_id};
             {#{owner_id := PFowner_id}, _} -> S4#{owner_id => PFowner_id};
             _ -> S4
         end,
    S6 = case {PMsg, NMsg} of
             {_, #{private := NFprivate}} -> S5#{private => NFprivate};
             {#{private := PFprivate}, _} -> S5#{private => PFprivate};
             _ -> S5
         end,
    S7 = case {PMsg, NMsg} of
             {#{created_at := PFcreated_at}, #{created_at := NFcreated_at}} -> S6#{created_at => merge_msg_timestamp(PFcreated_at, NFcreated_at, TrUserData)};
             {_, #{created_at := NFcreated_at}} -> S6#{created_at => NFcreated_at};
             {#{created_at := PFcreated_at}, _} -> S6#{created_at => PFcreated_at};
             {_, _} -> S6
         end,
    case {PMsg, NMsg} of
        {#{participant_ids := PFparticipant_ids}, #{participant_ids := NFparticipant_ids}} -> S7#{participant_ids => 'erlang_++'(PFparticipant_ids, NFparticipant_ids, TrUserData)};
        {_, #{participant_ids := NFparticipant_ids}} -> S7#{participant_ids => NFparticipant_ids};
        {#{participant_ids := PFparticipant_ids}, _} -> S7#{participant_ids => PFparticipant_ids};
        {_, _} -> S7
    end.

-compile({nowarn_unused_function,merge_msg_get_or_create_direct_request/3}).
merge_msg_get_or_create_direct_request(PMsg, NMsg, _) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {_, #{peer_user_id := NFpeer_user_id}} -> S1#{peer_user_id => NFpeer_user_id};
        {#{peer_user_id := PFpeer_user_id}, _} -> S1#{peer_user_id => PFpeer_user_id};
        _ -> S1
    end.

-compile({nowarn_unused_function,merge_msg_get_or_create_direct_response/3}).
merge_msg_get_or_create_direct_response(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {#{room := PFroom}, #{room := NFroom}} -> S1#{room => merge_msg_room(PFroom, NFroom, TrUserData)};
        {_, #{room := NFroom}} -> S1#{room => NFroom};
        {#{room := PFroom}, _} -> S1#{room => PFroom};
        {_, _} -> S1
    end.

-compile({nowarn_unused_function,merge_msg_create_channel_request/3}).
merge_msg_create_channel_request(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{name := NFname}} -> S1#{name => NFname};
             {#{name := PFname}, _} -> S1#{name => PFname};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {_, #{private := NFprivate}} -> S2#{private => NFprivate};
        {#{private := PFprivate}, _} -> S2#{private => PFprivate};
        _ -> S2
    end.

-compile({nowarn_unused_function,merge_msg_create_channel_response/3}).
merge_msg_create_channel_response(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {#{room := PFroom}, #{room := NFroom}} -> S1#{room => merge_msg_room(PFroom, NFroom, TrUserData)};
        {_, #{room := NFroom}} -> S1#{room => NFroom};
        {#{room := PFroom}, _} -> S1#{room => PFroom};
        {_, _} -> S1
