verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        room -> v_msg_room(Msg, [MsgName], TrUserData);
        get_or_create_direct_request -> v_msg_get_or_create_direct_request(Msg, [MsgName], TrUserData);
        get_or_create_direct_response -> v_msg_get_or_create_direct_response(Msg, [MsgName], TrUserData);
        create_channel_request -> v_msg_create_channel_request(Msg, [MsgName], TrUserData);
        create_channel_response -> v_msg_create_channel_response(Msg, [MsgName], TrUserData);
        get_room_request -> v_msg_get_room_request(Msg, [MsgName], TrUserData);
        get_room_response -> v_msg_get_room_response(Msg, [MsgName], TrUserData);
        check_membership_request -> v_msg_check_membership_request(Msg, [MsgName], TrUserData);
        check_membership_response -> v_msg_check_membership_response(Msg, [MsgName], TrUserData);
        list_rooms_request -> v_msg_list_rooms_request(Msg, [MsgName], TrUserData);
        room_summary -> v_msg_room_summary(Msg, [MsgName], TrUserData);
        list_rooms_response -> v_msg_list_rooms_response(Msg, [MsgName], TrUserData);
        add_member_request -> v_msg_add_member_request(Msg, [MsgName], TrUserData);
        add_member_response -> v_msg_add_member_response(Msg, [MsgName], TrUserData);
        member -> v_msg_member(Msg, [MsgName], TrUserData);
        list_members_request -> v_msg_list_members_request(Msg, [MsgName], TrUserData);
        list_members_response -> v_msg_list_members_response(Msg, [MsgName], TrUserData);
        remove_member_request -> v_msg_remove_member_request(Msg, [MsgName], TrUserData);
        remove_member_response -> v_msg_remove_member_response(Msg, [MsgName], TrUserData);
        leave_room_request -> v_msg_leave_room_request(Msg, [MsgName], TrUserData);
        leave_room_response -> v_msg_leave_room_response(Msg, [MsgName], TrUserData);
        message -> v_msg_message(Msg, [MsgName], TrUserData);
        send_message_request -> v_msg_send_message_request(Msg, [MsgName], TrUserData);
        send_message_response -> v_msg_send_message_response(Msg, [MsgName], TrUserData);
        list_messages_request -> v_msg_list_messages_request(Msg, [MsgName], TrUserData);
        list_messages_response -> v_msg_list_messages_response(Msg, [MsgName], TrUserData);
        timestamp -> v_msg_timestamp(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


-compile({nowarn_unused_function,v_submsg_room/3}).
-dialyzer({nowarn_function,v_submsg_room/3}).
v_submsg_room(Msg, Path, TrUserData) -> v_msg_room(Msg, Path, TrUserData).

-compile({nowarn_unused_function,v_msg_room/3}).
-dialyzer({nowarn_function,v_msg_room/3}).
v_msg_room(#{} = M, Path, TrUserData) ->
    case M of
        #{id := F1} -> v_type_string(F1, [id | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{kind := F2} -> 'v_enum_chat.v1.RoomKind'(F2, [kind | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{name := F3} -> v_type_string(F3, [name | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{owner_id := F4} -> v_type_string(F4, [owner_id | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{private := F5} -> v_type_bool(F5, [private | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{created_at := F6} -> v_submsg_timestamp(F6, [created_at | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{participant_ids := F7} ->
            if is_list(F7) ->
                   _ = [v_type_string(Elem, [participant_ids | Path], TrUserData) || Elem <- F7],
                   ok;
               true -> mk_type_error({invalid_list_of, string}, F7, [participant_ids | Path])
            end;
        _ -> ok
    end,
    lists:foreach(fun (id) -> ok;
                      (kind) -> ok;
                      (name) -> ok;
                      (owner_id) -> ok;
                      (private) -> ok;
                      (created_at) -> ok;
                      (participant_ids) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
v_msg_room(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), room}, M, Path);
v_msg_room(X, Path, _TrUserData) -> mk_type_error({expected_msg, room}, X, Path).

